import io, struct
import pandas as pd

def _make_data():
    # Load the real fixture bytes if present in the repo working dir.
    # The scenario text says the pack happens on dates_null.sas7bdat.
    path = "/workspace/buggy/dates_null.sas7bdat"
    try:
        with open(path, "rb") as f:
            return bytearray(f.read())
    except FileNotFoundError:
        path = "dates_null.sas7bdat"
        with open(path, "rb") as f:
            return bytearray(f.read())

dates_null_data = _make_data()

names_and_actions = [
    (
        'struct.pack_into("<d", data, 65816, -(2.0**63)) on dates_null.sas7bdat, then pd.read_sas(io.BytesIO(data), format="sas7bdat", encoding=None)',
        lambda data: (
            struct.pack_into("<d", data, 65816, -(2.0**63)),
            pd.read_sas(io.BytesIO(data), format="sas7bdat", encoding=None),
        )[1],
    ),
    (
        'struct.pack_into("<d", data, 65816, -1e300) on dates_null.sas7bdat, then pd.read_sas(io.BytesIO(data), format="sas7bdat", encoding=None)',
        lambda data: (
            struct.pack_into("<d", data, 65816, -1e300),
            pd.read_sas(io.BytesIO(data), format="sas7bdat", encoding=None),
        )[1],
    ),
    (
        'struct.pack_into("<d", data, 65816, 1e300) (what="date") or 65824 (what="datetime"), then pd.read_sas(io.BytesIO(data), format="sas7bdat", encoding=None)',
        lambda data: (
            struct.pack_into("<d", data, 65816, 1e300),
            pd.read_sas(io.BytesIO(data), format="sas7bdat", encoding=None),
        )[1],
    ),
    (
        'struct.pack_into("<d", data, 65816, 2.0**63) or (65824, 2.0**63) on dates_null.sas7bdat, then pd.read_sas(io.BytesIO(data), format="sas7bdat", encoding=None)',
        lambda data: (
            struct.pack_into("<d", data, 65816, 2.0**63),
            pd.read_sas(io.BytesIO(data), format="sas7bdat", encoding=None),
        )[1],
    ),
]

for description, action in names_and_actions:
    data = bytearray(dates_null_data)
    try:
        result = action(data)
        probe(description, result)
    except Exception as e:
        probe_exception(description, e)

